hooks.command:
cd "${CLAUDE_PROJECT_DIR:-.}" || exit 0
[ -z "$(git status --porcelain -- frontend backend shared api 2>/dev/null)" ] && exit 0
out=$(npm run typecheck 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("typecheck failed — fix before finishing:\n"+.)}'; exit 0; }
out=$(npm run test:coverage 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("tests or coverage failed — fix before finishing:\n"+.)}'; exit 0; }
exit 0
